        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AutocompleteService auto = new AutocompleteService(3); // top-3

        // Seed common banking queries with popularity (search counts)
        auto.seed("transfer money", 1000);
        auto.seed("transaction history", 800);
        auto.seed("track cheque", 300);
        auto.seed("transfer limit", 150);
        auto.seed("fixed deposit", 900);

        log.info(() -> "Suggestions for 'tra': " + auto.suggest("tra"));
        log.info(() -> "Suggestions for 'transf': " + auto.suggest("transf"));

        // A new feature query surges in usage
        for (int i = 0; i < 500; i++) auto.recordSearch("transfer to upi");
        auto.recomputeTopK();   // batched update
        log.info(() -> "After surge, 'tra': " + auto.suggest("tra"));
    }
}

