// ─── File: AutocompleteService.java ───
package com.bank.autocomplete;

import java.util.*;
import java.util.logging.*;

public class AutocompleteService {
    private static final Logger log = Logger.getLogger("Auto");
    private final Trie trie;

    public AutocompleteService(int k) { this.trie = new Trie(k); }

    public void seed(String query, long popularity) {
        trie.insert(query, popularity);
        trie.recomputeTopK();
    }

    // record a live search; ranking updated on next batch recompute
    public void recordSearch(String query) { trie.addFrequency(query, 1); }

    public List<String> suggest(String prefix) {
        List<String> s = trie.suggest(prefix);
        log.fine(() -> "suggest(" + prefix + ") = " + s);
        return s;
    }

    public void recomputeTopK() {
        trie.recomputeTopK();
        log.info("recomputed top-K from latest query logs");
    }
}
```
